ee:message.ee:set-payload:
%dw 2.0
output application/json
var s = payload.content[0]
var addr = s.address default {}
var sd = s.salesData default {}
var ms = s.msisdn default {}
var ba = s.billingAccount default {}
var sub = s.subscriber default {}
var links = sub.links default []
var pp = s.priceplan default {}
---
{
  responseCode: "200",
  response: "OK",
  balance: {
    id: s.id,
    confirmationDate: s.lastUpdate,
    requestedDate: s.creationDate,
    amount: {
      amount: s.balance
    },
    bucket: {
      id: addr.externalID,
      name: addr.description
    },
    channel: {
      id: sd.salesChannel,
      name: sd.salesChannel
    },
    logicalResource: [
      {
        id: ms.id,
        name: ms.name
      }
    ],
    partyAccount: {
      id: ba.id,
      name: ba.name,
      status: s.status
    },
    receiver: {
      id: sub.id,
      href: if (sizeOf(links) > 0) links[0].href else null,
      name: sub.name
    },
    receiverBucket: {
      id: addr.externalID,
      name: addr.description
    },
    receiverProduct: {
      id: pp.id,
      name: pp.pricePlanName default pp.name
    },
    requestor: {
      id: sd.salesPerson,
      name: sd.salesPerson
    },
    status: s.status,
    validFor: {
      startDateTime: s.creationDate,
      endDateTime: s.lastUpdate
    }
  }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
    amount: {
        amount: vars.inputPayload.monto,
        currency: p('jsc-sapi.transferbalance.currency')
    },
    subscription: vars.sidDestino,
    msisdn: vars.inputPayload.msisdnDest,
    channel: p('jsc-sapi.transferbalance.channel'),
    comment: p('jsc-sapi.transferbalance.comment')
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"status": 500,
	"code": "TRANSFER_BALANCE",
	"message": {
	  "message": vars.errorMessageOutput
	},
	"messageServer": "Error transfering balance",
	"cause": [
	  {
	    "origin": app.name,
	    "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
	  }
	]
}
